--
-- Name: get_breadcrumb(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_breadcrumb(node_id uuid) RETURNS TABLE(id uuid, name text, slug text, level integer)
    LANGUAGE sql
    AS $$
WITH RECURSIVE breadcrumb AS (
    SELECT id, parent_id, name, slug, 1 AS level
    FROM categories
    WHERE id = node_id
    UNION ALL
    SELECT c.id, c.parent_id, c.name, c.slug, b.level + 1
    FROM categories c
    JOIN breadcrumb b ON c.id = b.parent_id
)
SELECT id, name::text, slug::text, level
    FROM breadcrumb
    ORDER BY level DESC;
$$;


--
-- Name: get_category_tree(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_category_tree() RETURNS jsonb
    LANGUAGE sql
    AS $$
WITH RECURSIVE category_tree AS (
    SELECT id, parent_id, name, slug, icon, sort_order,
           jsonb '[]' AS children
    FROM categories
    WHERE parent_id IS NULL AND is_active = TRUE

    UNION ALL

    SELECT c.id, c.parent_id, c.name, c.slug, c.icon, c.sort_order,
           jsonb '[]' AS children
    FROM categories c
    INNER JOIN category_tree ct ON c.parent_id = ct.id
    WHERE c.is_active = TRUE
)
SELECT jsonb_agg(row_to_json(category_tree)) FROM category_tree;
$$;


--
-- Name: update_modified_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_modified_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;


